{"content":""""Modernized climate data analysis script (Python 3)."""

from pathlib import Path
import configparser

import pandas as pd

BASE_DIR = Path(__file__).resolve().parent
DEFAULT_DATA_PATH = BASE_DIR / "climate_analyzer" / "sample_data" / "climate_data.csv"
DEFAULT_CONFIG_PATH = BASE_DIR / "climate_analyzer" / "config.ini"


def load_config(config_path: Path) -> configparser.ConfigParser:
    """Read configuration file using modern configparser API."""
    config = configparser.ConfigParser()
    if config_path.is_file():
        config.read(config_path, encoding="utf-8")
    return config


def load_temperature_data(csv_path: Path) -> pd.DataFrame:
    """Load temperature data with explicit UTF-8 encoding."""
    return pd.read_csv(csv_path, encoding="utf-8", parse_dates=["date"])


def print_station_means(df: pd.DataFrame) -> None:
    """Calculate and print mean temperature for each station."""
    for station_id, group in sorted(df.groupby("station_id")):
        mean_temp = group["temperature"].mean()
        print(f"Station {station_id} mean temperature: {mean_temp:.1f}°C")


def main(
    data_path: Path = DEFAULT_DATA_PATH,
    config_path: Path = DEFAULT_CONFIG_PATH,
) -> None:
    config = load_config(Path(config_path))
    _ = config  # Config retained for future analysis/plotting options.
    df = load_temperature_data(Path(data_path))
    print_station_means(df)


if __name__ == "__main__":
    main()
